  var moovEnd = BL;
  var top = RG_boxes(headB, 0, Math.min(BL, 2000000));
  for (var i=0;i<top.length;i++){ if(top[i].t==='moov'){ moovEnd=top[i].p+top[i].s; break; } }
  // 总大小：★遍历找 mdat（moov 之后可能有 free/skip 等 box）
  var total = moovEnd;
  var mdatAt = -1;
  var lim = Math.min(BL - 8, moovEnd + 200000);
  for (var q = moovEnd; q < lim; q++) {
    if (RG_STR(headB, q+4, 4) === 'mdat') {
      mdatAt = q;
      total = q + RG_U32(headB, q);
      break;
    }
  }
  // 兜底：用样本最大偏移 + size
  if (mdatAt < 0) {
    var maxEnd = moovEnd;
    // samples 在后面构建，此处先用 stco 粗估
    var stbls0 = RG_find(headB, 28, Math.min(moovEnd, BL), 'stbl');
    for (var z0=0; z0<stbls0.length; z0++){
      var kids0 = RG_boxes(headB, stbls0[z0].p+8, Math.min(stbls0[z0].p+stbls0[z0].s, BL));
      for (var z1=0; z1<kids0.length; z1++){
        if (kids0[z1].t === 'stco') {
          var nch0 = RG_U32(headB, kids0[z1].p+12);
          var lastOff = RG_U32(headB, kids0[z1].p+16+(nch0-1)*4);
          if (lastOff > maxEnd) maxEnd = lastOff;
        }
      }
    }
    if (maxEnd > total) total = maxEnd + 1000000;   // 粗估最后一个 chunk 大小
  }
  // fourcc 修复位置（encv/enca → hvc1/mp4a，sinf → free）
  var fixes = [];
  var stsdL = RG_find(headB, 28, Math.min(moovEnd, BL), 'stsd');
  for (var si=0; si<stsdL.length; si++){
    var kk = RG_boxes(headB, stsdL[si].p+16, stsdL[si].p+stsdL[si].s);
    for (var k=0;k<kk.length;k++){
      var e = kk[k];
      if (e.t==='encv'||e.t==='enca'){
        fixes.push({pos: e.p+4, to: (e.t==='encv') ? 'hvc1' : 'mp4a'});
        // 找内部 sinf
        var eEnd = Math.min(e.p+e.s, BL);
        for (var p3=e.p+8; p3+8<=eEnd; p3++){
          if ((headB[p3]&255)===0x73&&(headB[p3+1]&255)===0x69&&(headB[p3+2]&255)===0x6e&&(headB[p3+3]&255)===0x66){
            var sz4 = RG_U32(headB, p3-4);
            if (sz4>=8 && p3-4+sz4<=BL){
              fixes.push({pos: p3, to: 'free', zeroFrom: p3+4, zeroTo: p3-4+sz4});
              p3 = p3-4+sz4-1;
            }
          }
        }
      }
    }
  }
  // 样本索引
  var samples = [];
  var stbls = RG_find(headB, 28, Math.min(moovEnd, BL), 'stbl');
  for (var si2=0; si2<stbls.length; si2++){
    var sp = stbls[si2].p, ss = stbls[si2].s;
    var kids = RG_boxes(headB, sp+8, Math.min(sp+ss, BL));
    var senc=null, stsz=null, stco=null, stsc=null;
    for (var i2=0;i2<kids.length;i2++){
      if(kids[i2].t==='senc') senc=kids[i2];
      if(kids[i2].t==='stsz') stsz=kids[i2];
      if(kids[i2].t==='stco') stco=kids[i2];
      if(kids[i2].t==='stsc') stsc=kids[i2];
    }
    if(!senc||!stsz||!stco||!stsc) continue;
    var dflt = RG_U32(headB, stsz.p+12), cnt = RG_U32(headB, stsz.p+16);
    var nch = RG_U32(headB, stco.p+12), nent = RG_U32(headB, stsc.p+12);
    var ef=[], es=[];
    for (var j=0;j<nent;j++){ ef.push(RG_U32(headB, stsc.p+16+j*12)); es.push(RG_U32(headB, stsc.p+16+j*12+4)); }
    var sidx=0, eidx=0;
    for (var c=0; c<nch && sidx<cnt; c++){
      while(eidx+1<nent && ef[eidx+1] <= c+1) eidx++;
      var spc = es[eidx];
      var off = RG_U32(headB, stco.p+16+c*4);
      for (var k2=0; k2<spc && sidx<cnt; k2++){
        var size = dflt ? dflt : RG_U32(headB, stsz.p+20+sidx*4);
        var ivOff = senc.p+16+sidx*8;
        samples.push({off: off, size: size, iv: [
          headB[ivOff]&255, headB[ivOff+1]&255, headB[ivOff+2]&255, headB[ivOff+3]&255,
          headB[ivOff+4]&255, headB[ivOff+5]&255, headB[ivOff+6]&255, headB[ivOff+7]&255
        ]});
        off += size; sidx++;
      }
    }
  }
  return {total: total, moovEnd: moovEnd, fixes: fixes, samples: samples};
}

// 对单个块做解密（blockStart = 块在文件中的起始偏移）
function RG_decryptBlock(block, blockStart, keyHex, samples){
  var BL = block.length;
  var sk = new RG_SK(RG_H2B(keyHex), 'AES');
  var cnt = 0;
  // 二分找到第一个可能重叠的样本
  var lo = 0, hi = samples.length - 1, start = samples.length;
  while (lo <= hi) {
    var mid = (lo + hi) >> 1;
    if (samples[mid].off + samples[mid].size > blockStart) { start = mid; hi = mid - 1; }
    else lo = mid + 1;
  }
  for (var i = start; i < samples.length; i++){
    var s = samples[i];
    if (s.off >= blockStart + BL) break;
    var gEnd = s.off + s.size;
    if (gEnd <= blockStart) continue;
    var os = Math.max(s.off, blockStart) - blockStart;
    var oe = Math.min(gEnd, blockStart + BL) - blockStart;
    if (oe <= os) continue;
    var iv16 = RG_S2B(String.fromCharCode(s.iv[0], s.iv[1], s.iv[2], s.iv[3], s.iv[4], s.iv[5], s.iv[6], s.iv[7], 0,0,0,0,0,0,0,0));
    var cph = RG_CIPHER.getInstance('AES/CTR/NoPadding');
    cph.init(RG_CIPHER.DECRYPT_MODE, sk, new RG_IVP(iv16));
    var dec = cph.doFinal(RG_ARR.copyOfRange(block, os, oe));
    RG_SYS.arraycopy(dec, 0, block, os, oe - os);
    cnt++;
  }
  return cnt;
}

// 应用 fourcc 修复到块（如果块包含修复位置）
function RG_applyFixes(block, blockStart, fixes){
  for (var i=0; i<fixes.length; i++){
    var f = fixes[i];
    if (f.pos >= blockStart && f.pos + 4 <= blockStart + block.length) {
      var p = f.pos - blockStart;
      block[p] = f.to.charCodeAt(0); block[p+1] = f.to.charCodeAt(1);
      block[p+2] = f.to.charCodeAt(2); block[p+3] = f.to.charCodeAt(3);
      if (f.zeroFrom !== undefined) {
        var zs = Math.max(f.zeroFrom, blockStart) - blockStart;
        var ze = Math.min(f.zeroTo, blockStart + block.length) - blockStart;
        for (var z = zs; z < ze; z++) block[z] = 0;
      }
    }
  }
}


