// 括号配平提取 JSON 数组/对象
function HG_jsonArray(text, marker){
var i=String(text).indexOf(marker);
if(i<0) return null;
var j=i+marker.length;
while(j<text.length && (text[j]===' '||text[j]===String.fromCharCode(10)||text[j]===String.fromCharCode(9))) j++;
var open=text[j];
if(open!=='[' && open!=='{') return null;
var close=open==='['?']':'}';
var depth=0,quoted=false,esc=false,end=j;
for(;end<text.length;end++){
var ch=text[end];
if(quoted){ if(esc)esc=false; else if(ch===String.fromCharCode(92))esc=true; else if(ch===String.fromCharCode(34))quoted=false; continue; }
if(ch===String.fromCharCode(34))quoted=true;
else if(ch===open)depth++;
else if(ch===close && --depth===0) break;
}
try{ return JSON.parse(text.substring(j,end+1)); }catch(e){ return null; }
}
