// --- 正文：取播放直链 ---
function HG_play(JV, vid, sid){
var BP={detail_page_version:0,device_level:3,disable_digg_stat:false,need_all_video_definition:true,
need_mp4_align:false,use_os_player:false,use_server_dns:false,video_platform:1024};
var r=HG_API(JV,'/novel/player/multi_video_model/preload/v1',{biz_param:BP,dr_scene:'preload',mixed_video_id_map:{'1004':[vid]}});
var j=null; try{ j=JSON.parse(String(r)); }catch(e){}
if(!j||j.code!==0||!j.data) return null;
var item=j.data[vid];
if(!item) return null;
var vm=null; try{ vm=JSON.parse(item.video_model); }catch(e){}
if(!vm||!vm.video_list||!vm.video_list.length) return null;
// 选最高清晰度
var best=null,bestScore=-1;
for(var i=0;i<vm.video_list.length;i++){
var v=vm.video_list[i];
if(!v.main_url) continue;
var meta=v.video_meta||{};
var def=parseInt(String(meta.definition||'0'),10)||0;
if(def<100){ var mm=String(meta.definition||'').match(/([0-9]+)/); def=mm?parseInt(mm[1],10):0; }
var sc=def*1000000+(parseInt(meta.vwidth||0,10)*parseInt(meta.vheight||0,10));
if(sc>bestScore){ bestScore=sc; best=v; }
}
if(!best) return null;
return {url:String(best.main_url),backup:String(best.backup_url||''),def:String((best.video_meta||{}).definition||''),expire:vm.url_expire||item.expire_time||0};
}
