// 裁剪解密缓存：只保留最近 N 个，其余删除（避免缓存无限堆积）
function RG_trimCache(JV, SV){
  try {
    var keys = String(SV.get('rg_keys') || '');
    var arr = keys ? keys.split(',') : [];
    // 新键已在规则里 put，这里把当前键加入列表
    // 保留最近 8 个
    var MAXK = 8;
    while (arr.length > MAXK) {
      var oldKey = arr.shift();
      try {
        var p = String(SV.get(oldKey) || '');
        if (p) { try { JV.deleteFile(p); } catch(e1) {} }
        SV.put(oldKey, '');
      } catch(e2) {}
    }
    SV.put('rg_keys', arr.join(','));
  } catch(e3) {}
}

