// off=0 首屏（change_type=2），off>0 翻页（change_type=1）；sid 必须回传（服务端绑设备）
function FV_feed(JV, tabType, cellId, off, sid){
  var ex={cell_id:cellId,tab_type:String(tabType),client_template:'2',client_req_type:'2',
    offset:String(off),unlimited_selector_change_type:(off>0?'1':'2')};
  if(sid) ex.session_id=sid;
  var r=FV_get(JV,'/reading/bookapi/bookmall/cell/change/v1/',ex);
