  var d=j.data||{};
  return d;
}

// —— 从任意 cell 树里递归收集 video_data ——
function FV_collect(node, out){
  if(!node) return out;
  if(Array.isArray(node)){
    for(var i=0;i<node.length;i++) FV_collect(node[i],out);
    return out;
  }
  var vd=node.video_data;
  if(vd){
    if(Array.isArray(vd)){ for(var m=0;m<vd.length;m++) out.push(vd[m]); }
    else out.push(vd);
  }
  var sub=node.cell_data;
  if(sub) FV_collect(sub,out);
  return out;
}

// —— video_data → 书源条目 ——
function FV_item(v){
  if(!v) return null;
  var sid=String(v.series_id||'');
  if(!sid) return null;
  var t=String(v.title||v.series_title||'').trim();
  if(!t) return null;
  var k=[];
  if(v.episode_cnt) k.push(String(v.episode_cnt)+'集');
  if(v.vertical===false) k.push('横屏');
  if(v.score) k.push(String(v.score)+'分');
  if(v.play_cnt) k.push(String(Math.round(Number(v.play_cnt)/10000))+'万播放');
  return JSON.stringify({name:t,author:'番茄短剧',kind:k.join(' · '),
    intro:String(v.video_desc||v.series_intro||''),
    coverUrl:String(v.cover||v.series_cover||''),
    bookUrl:'https://api5-normal-sinfonlineb.fqnovel.com/detail?series_id='+sid});
}

// —— 发现页入口：解析出 kind 与 page 后调对应通道 ——
// kind: manju(漫剧32) / zhaoju(找剧8) / dongman(动漫24)
function FV_explore(JV, SV, kind, page){
  var ttMap={manju:32,zhaoju:8,dongman:24};
  var tt=ttMap[kind]; if(!tt) return [];
  var pg=parseInt(page||'1',10)||1;
  // cell 缓存（同一书源会话内复用；服务端 cell_id 数天不变）
  var ck='fv_cell_'+tt;
  var cellId='', sid='';
  try{ cellId=String(SV.get(ck)||''); }catch(e){}
  if(!cellId){
    var t=FV_tab(JV,tt);
    if(!t) throw new Error('发现页加载失败：无法获取频道数据（'+tt+'）');
    var c=t.cell_data&&t.cell_data[0]?t.cell_data[0].cell_id_str:'';
    if(!c) throw new Error('发现页加载失败：频道无 cell');
    cellId=String(c);
    try{ SV.put(ck,cellId); }catch(e2){}
  }
  // 翻页需要 session：首屏先取一次
  var sk='fv_sid_'+tt;
  try{ sid=String(SV.get(sk)||''); }catch(e3){}
  var off=(pg-1)*6;
  var d=FV_feed(JV,tt,cellId,off,sid);
  if(!d){
    // session 失效 → 重新开一次首屏拿新 session 后重试
    var t2=FV_tab(JV,tt);
    if(t2&&t2.session_id){ sid=String(t2.session_id); try{ SV.put(sk,sid); }catch(e4){} }
    d=FV_feed(JV,tt,cellId,off,sid);
  }
  if(!d) throw new Error('发现页加载失败：视频流为空');
  if(d.session_id){ try{ SV.put(sk,String(d.session_id)); }catch(e5){} }
  var arr=FV_collect((d.cell_view&&d.cell_view.cell_data)||[],[]);
  var out=[]; var seen={};
  for(var i=0;i<arr.length;i++){
    var it=FV_item(arr[i]);
    if(!it) continue;
    var o=JSON.parse(it);
    if(seen[o.bookUrl]) continue;
    seen[o.bookUrl]=1;
    out.push(it);
  }
  // has_more=false 且是最后一页 → 返回空数组让 Legado 停止翻页
  if(d.has_more===false && out.length===0) return [];
  return out;
}

// —— 搜索：suggest 通道（含视频结果）——
