var A551_SK=HG_h2b('fc78e0a9657a0c748ce51559903ccf03510e51d3cff232d71343e88a321c5304');
var A551_AK=HG_h2b('d31e3718288a1027baab59f146a09a9c');
var A551_IV=HG_h2b('ea180a0336ed352fcd24e4d50018ae54');
function A551_simon(pb){
  var key=[];for(var i=0;i<4;i++)key.push(HG_r64(A551_SK,i*8));
  var ks=[];for(var z=0;z<4;z++)ks.push(key[z]);
  for(var x=4;x<72;x++){var m=HG_xor(HG_ror(ks[x-1],3),ks[x-3]);m=HG_xor(m,HG_ror(m,1));
    ks.push(HG_xor(HG_n64(ks[x-4]),m,HG_zbit((x-4)%62),HG_w64(3,0)));}
  var out=new Uint8Array(pb.length);
  for(var o=0;o<pb.length;o+=16){
    var blk=pb.slice(o,o+16);
    var xi=HG_r64(blk,0),xi1=HG_r64(blk,8);
    for(var y=0;y<72;y++){var tmp=xi1;var f=HG_a64(HG_rol(xi1,1),HG_rol(xi1,8));
      xi1=HG_xor(xi,f,HG_rol(xi1,2),ks[y]);xi=tmp;}
    HG_w64le(out,o,xi);HG_w64le(out,o+8,xi1);
  }
  return out;
}
// AES-CBC without any extra padding: input must already be block aligned.
function A551_aesNP(data,key,iv){
  var C=Packages.javax.crypto.Cipher;
  var c=C.getInstance('AES/CBC/NoPadding');
  c.init(C.ENCRYPT_MODE,new Packages.javax.crypto.spec.SecretKeySpec(HG_jb(key),'AES'),
    new Packages.javax.crypto.spec.IvParameterSpec(HG_jb(iv)));
  return HG_j2u(c.doFinal(HG_jb(data)));
}
function A551_bean(q,stubHex,ts,aid,deviceId,licenseId,versionName,installId,randField){
  var sub15=HG_cat(HG_pbv(1,1),HG_pbv(2,1),HG_pbv(3,1),HG_pbv(7,0xC792ECCC));
  var sub23=HG_cat(HG_pbb(1,'NX551J'),HG_pbv(2,8196),HG_pbv(4,0x80E0D800));
  var stubRaw=(/^[0-9a-f]{32}$/i.test(stubHex))?HG_h2b(stubHex):new Uint8Array(16);
  return HG_cat(
    HG_pbv(1,1077940818),HG_pbv(2,2),HG_pbv(3,randField>>>0),
    HG_pbb(4,String(aid)),HG_pbb(5,String(deviceId)),HG_pbb(6,String(licenseId)),
    HG_pbb(7,String(versionName||'')),
    HG_pbb(8,'v04.04.05-ov-android'),HG_pbv(9,134744640),HG_pbb(10,new Uint8Array(8)),
    HG_pbv(11,0),HG_pbv(12,ts*2),
    HG_pbb(13,HG_sm3(stubRaw).slice(0,6)),
    HG_pbb(14,HG_sm3(HG_u8(q)).slice(0,6)),
    HG_pbb(15,sub15),
    HG_pbb(16,String(installId||'')),
    HG_pbb(20,'none'),HG_pbv(21,738),
    HG_pbb(23,sub23),HG_pbv(25,2));
}
function HG_argusV3(q,stubHex,ts,op){
  op=op||{};
  var MAG=HG_h2b('f2f7fcfff2f7fcff'),TAIL=HG_h2b('eafb2cfe8568519154');
  var bean=A551_bean(q,stubHex,ts,op.aid||1967,op.deviceId||'',op.licenseId||1611921764,op.versionName||'',op.installId||'',op.randField||0);
  var pb=HG_pad(bean);
  var enc=A551_simon(pb);
  var un=HG_cat(MAG,enc,TAIL);
  var buf=new Uint8Array(un.length);
  buf.set(MAG,0);
  for(var i=8;i<un.length;i++)buf[i]=un[i]^MAG[i%8];
  var rev=HG_rev(buf);
  var cont=HG_cat(rev,new Uint8Array([0x61,0x6f]));
  var fin=HG_pad(cont);
  var ct=A551_aesNP(fin,A551_AK,A551_IV);
  return HG_b64(HG_cat(HG_h2b('f281'),ct));
}

// x-argus 必须用 551 封装 + AES/CBC/NoPadding；旧的 PKCS5 封装会被上游拒签（响应体为空）
function HG_argus(q,stub,ts,op){op=op||{};
  var aid=parseInt(HG_qp(q,'aid'),10)||1967;
  var did=HG_qp(q,'device_id')||'4439167111850522';
