// 那条兜底既慢又依赖 WebView，这里不保留。
function alsContent(J,base){
  try{
    var html=String(J.ajax(base));
    var doc=org.jsoup.Jsoup.parse(html);
    var box=doc.select("div.read-content");
    if(box.size()<1)return '';
    box.select("script, style, .ad-block").remove();
    var txt=box.html();
    if(!txt||txt.length<50)return '';
    return txt;
  }catch(e){J.log('als正文失败: '+e);return '';}
}

