// 搜索：网页版 /search/{kw} 的 searchBookList 恒为空（实测），只能走 App 签名接口
function FQ_search(JV,kw){
  var out=[];
  if(!kw) return out;
  try{
    var r=String(FV_get(JV,'/reading/bookapi/search/page/v',{query:kw,keyword:kw,q:kw,offset:'0',count:'10'}));
    var j=JSON.parse(r);
    var books=[];
    (function walk(n){
      if(!n) return;
      if(Array.isArray(n)){ for(var i=0;i<n.length;i++) walk(n[i]); return; }
      if(typeof n!=='object') return;
      if(n.book_data){
        if(Array.isArray(n.book_data)){ for(var q=0;q<n.book_data.length;q++) books.push(n.book_data[q]); }
        else books.push(n.book_data);
      }
      for(var k in n){ if(k==='book_data') continue; var v=n[k]; if(v&&typeof v==='object') walk(v); }
    })(j.data);
    for(var b=0;b<books.length;b++){
      var it=books[b];
      var bid=String(it.book_id||'');
      if(!bid) continue;
      var kind=[];
      if(it.category) kind.push(String(it.category));
      if(it.word_number) kind.push((Number(it.word_number)/10000).toFixed(0)+'万字');
      if(it.creation_status!==undefined) kind.push(String(it.creation_status)==='0'?'连载中':'已完结');
